// Original PNG/WAV masters remain available for editing and file previews.
// WebP derivatives are generated by prepareWebAssets.mjs without resizing.
export function getWebAssetPath(asset) {
  if (/^assets\/(images|future)\/.+\.png$/.test(asset)) {
    return asset.replace(/^assets\//, "assets/optimized/").replace(/\.png$/, ".webp");
  }
  if (/^assets\/audio\/bgm\/bgm_menu_0[1-6]\.wav$/.test(asset)) {
    return asset.replace(/\.wav$/, ".mp3");
  }
  return asset;
}
